with.script:
if (context.ref !== 'refs/heads/main') throw new Error('Deployments require main');
const {owner, repo} = context.repo;
const main = await github.rest.git.getRef({owner, repo, ref: 'heads/main'});
if (main.data.object.sha !== context.sha) throw new Error('Dispatch the current main commit');
for (const workflow_id of ['verify.yml', 'repository-hygiene.yml']) {
  const runs = await github.rest.actions.listWorkflowRuns({owner, repo, workflow_id, head_sha: context.sha, event: 'push', per_page: 20});
  const run = runs.data.workflow_runs[0];
  if (!run || run.status !== 'completed' || run.conclusion !== 'success') {
    throw new Error(`${workflow_id} must pass on ${context.sha} before deployment`);
  }
}

