with.script:
const checks = await github.paginate(github.rest.checks.listForRef, {
  ...context.repo, ref: context.sha, per_page: 100
});
for (const name of ['verify', 'publication-hygiene']) {
  const check = checks.filter(item => item.name === name).sort((a, b) => b.id - a.id)[0];
  if (!check || check.conclusion !== 'success') core.setFailed(`Required successful check missing: ${name}`);
}

